use semio_framework_test_fixtures::fixture_text;
use super::*;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
#[derive(semio_framework_value::RetireOwned,Debug,PartialEq)]struct Added<T:RetireOwned>{index:usize,value:T}
struct Mapper;
impl RetainedIndexedMap<String,Added<String>> for Mapper{const WORK:u64=2;fn map(index:usize,value:String)->Added<String>{Added{index,value}}}
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(v,(h.requested_bytes,h.released_bytes))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"indexed original action must fit4KiB: {}",d.copy_bytes);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(v:T)->RetainedCloneSource<T>{let mut admission=RetainedCloneSource::admission_owned(v,());let mut output=None;for _ in 0..64{if admission.terminal_is_empty(){break}let g=grant(admission.next_demand().unwrap());if admission.phase()=="ready"{admission.take_output(&mut output,g).result.unwrap();}else{let mut actual=None;admission.advance(g,&mut actual).result.unwrap();}}output.expect("staged source admission")}
fn close_source<T:RetireOwned+Sync+'static>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let g=grant(s.next_close_demand(4096).unwrap());assert!(s.close_step(g).result.unwrap().progress().fits(g));}}
fn drain<T:RetireOwned>(v:T){let mut c=ControlledRetirement::new(v).map_err(|(e,_)|e).unwrap();while !c.terminal_is_empty(){let g=grant(c.next_demand(4096).unwrap());assert!(c.step(g).unwrap().progress().fits(g));}}
fn strings(v:&serde_json::Value)->Vec<String>{v.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect()}
fn exercise(row:&serde_json::Value,cut:Option<usize>,body:usize,work:u64){observe(||());let mut a=source(strings(&row["authored"]));let mut o=source(strings(&row["original"]));let mut foreign=source(strings(&row["authored"]));let pointers=(a.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>(),o.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>());let(mut p,heap)=observe(||RetainedIndexedReplacement::<String,Added<String>,Mapper>::new());assert_eq!(heap,(0,0));let mut turns=0;while !p.ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.demand(a.borrow(),o.borrow(),body,work).unwrap());let mut denied_actual=None;let(step,heap)=observe(||p.advance(a.borrow(),o.borrow(),body,work,RetainedCloneGrant{maximum_items:0,..g},&mut denied_actual).result.unwrap());assert!(denied_actual.is_none());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));let moved=if p.phase==5{p.source.as_ref().and_then(|s|s.front().map(|v|v.as_ptr()))}else{None};let before=p.added.as_ref().map_or(0,Vec::len);let quoted=p.work_demand(a.borrow(),o.borrow(),body,work).unwrap();let mut denied_actual=None;let denied=p.advance(a.borrow(),o.borrow(),body,0,g,&mut denied_actual);assert!(denied_actual.is_none());assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());let mut actual=None;let(turn,heap)=observe(||p.advance(a.borrow(),o.borrow(),body,work,g,&mut actual));assert!(turn.work>0&&turn.work<=quoted);let receipt=turn.result.unwrap().progress();if let Some(bytes)=actual{assert_eq!(bytes,receipt.retained_capacity_bytes);}assert!(receipt.fits(g));assert_eq!(heap.0,receipt.retained_capacity_bytes,"indexed actual allocation receipt");assert_eq!(heap.1,receipt.released_bytes,"indexed actual release receipt");if let Some(pointer)=moved{if p.added.as_ref().map_or(0,Vec::len)>before{assert_eq!(p.added.as_ref().unwrap().last().unwrap().value.as_ptr(),pointer);}}turns+=1;assert!(turns<10000);}if turns>0{assert!(p.demand(foreign.borrow(),o.borrow(),body,work).is_err());}if cut.is_none(){let g=grant(p.take_demand().unwrap());let(out,receipt)=p.take(g).unwrap().unwrap();assert!(receipt.fits(g));assert_eq!(out.is_none(),row["expected"].is_null());if let Some(out)=out{assert_eq!(out.removed,(0..o.borrow().get().len()).collect::<Vec<_>>());assert_eq!(out.added.iter().map(|v|(v.index,&v.value)).collect::<Vec<_>>(),a.borrow().get().iter().enumerate().collect::<Vec<_>>());drain(out);}}p.begin_close();while !p.terminal_is_empty(){let g=grant(p.close_demand(4096).unwrap());assert_eq!(p.close_step(RetainedCloneGrant{maximum_items:0,..g}).result.unwrap().progress(),Default::default());let quoted=p.close_work_demand(g.maximum_copy_bytes).unwrap();let(turn,heap)=observe(||p.close_step(g));assert!(turn.work>0&&turn.work<=quoted);let receipt=turn.result.unwrap().progress();assert!(receipt.fits(g));assert_eq!(heap.0,receipt.retained_capacity_bytes);assert_eq!(heap.1,receipt.released_bytes);}assert_eq!(observe(||drop(p)).1,(0,0));assert_eq!((a.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>(),o.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>()),pointers);close_source(&mut a);close_source(&mut o);close_source(&mut foreign);}
#[test]fn indexed_replacement_original_rows_and_moved_payloads_match_neutral_cases(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/📋️indexed/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){exercise(row,None,f["bodyBytes"].as_u64().unwrap()as usize,f["workUnits"].as_u64().unwrap());}}
#[test]fn indexed_replacement_partial_original_deque_and_output_children_close(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/📋️indexed/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){for cut in f["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;exercise(row,Some(cut),f["bodyBytes"].as_u64().unwrap()as usize,f["workUnits"].as_u64().unwrap());}}}
#[test]fn indexed_replacement_records_a_refused_backing_allocation_and_closes_originals(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/📋️indexed/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let row=f["cases"].as_array().unwrap().iter().find(|row|row["id"]=="set").unwrap();let body=f["bodyBytes"].as_u64().unwrap()as usize;let work=f["workUnits"].as_u64().unwrap();let mut a=source(strings(&row["authored"]));let mut o=source(strings(&row["original"]));let mut p=RetainedIndexedReplacement::<String,Added<String>,Mapper>::new();while p.phase!=3{let g=grant(p.demand(a.borrow(),o.borrow(),body,work).unwrap());let mut actual=None;p.advance(a.borrow(),o.borrow(),body,work,g,&mut actual).result.unwrap();}let g=grant(p.demand(a.borrow(),o.borrow(),body,work).unwrap());let mut actual=None;let(turn,refused)=crate::test_allocation::refuse_one_allocation_on_this_thread(||p.advance(a.borrow(),o.borrow(),body,work,g,&mut actual));assert_eq!(refused,1);assert_eq!(actual,Some(0));assert!(turn.result.is_err());assert_eq!(p.phase,3);p.begin_close();while !p.terminal_is_empty(){let g=grant(p.close_demand(4096).unwrap());p.close_step(g).result.unwrap();}close_source(&mut a);close_source(&mut o);}
